import os
import base64
import google.cloud.documentai_v1 as documentai

def extract_layout(payload, config=None):
    config = config or {}
    client = documentai.DocumentProcessorServiceClient()
    project_id = config.get('project_id', os.environ.get('GOOGLE_CLOUD_PROJECT'))
    location = config.get('location', 'us')
    processor_id = config.get('processor_id', os.environ.get('DOCUMENT_AI_PROCESSOR_ID'))
    name = client.processor_path(project_id, location, processor_id)
    raw_document = documentai.RawDocument(content=payload, mime_type=config.get('mime_type', 'application/pdf'))
    request = documentai.ProcessRequest(name=name, raw_document=raw_document)
    response = client.process_document(request=request)
    result = []
    for page in response.document.pages:
        for block in page.blocks:
            block_text = ''
            for segment in block.layout.text_anchor.text_segments:
                start_index = segment.start_index
                end_index = segment.end_index
                block_text += response.document.text[start_index:end_index]
            result.append({
                'type': 'block',
                'text': block_text,
                'bounding_box': [(vertex.x, vertex.y) for vertex in block.layout.bounding_poly.normalized_vertices]
            })
        for line in page.lines:
            line_text = ''
            for segment in line.layout.text_anchor.text_segments:
                start_index = segment.start_index
                end_index = segment.end_index
                line_text += response.document.text[start_index:end_index]
            result.append({
                'type': 'line',
                'text': line_text,
                'bounding_box': [(vertex.x, vertex.y) for vertex in line.layout.bounding_poly.normalized_vertices]
            })
        for table in page.tables:
            table_data = []
            for row in table.header_rows:
                row_cells = []
                for cell in row.cells:
                    cell_text = ''
                    for segment in cell.layout.text_anchor.text_segments:
                        start_index = segment.start_index
                        end_index = segment.end_index
                        cell_text += response.document.text[start_index:end_index]
                    row_cells.append(cell_text)
                table_data.append(row_cells)
            for row in table.body_rows:
                row_cells = []
                for cell in row.cells:
                    cell_text = ''
                    for segment in cell.layout.text_anchor.text_segments:
                        start_index = segment.start_index
                        end_index = segment.end_index
                        cell_text += response.document.text[start_index:end_index]
                    row_cells.append(cell_text)
                table_data.append(row_cells)
            result.append({
                'type': 'table',
                'data': table_data,
                'bounding_box': [(vertex.x, vertex.y) for vertex in table.layout.bounding_poly.normalized_vertices]
            })
    return result
